137	                return;
138	            }
139	
140	            this.removeDeletedPlaylistsFromSectionMemory(playlistIds);
141	
142	            if (routeId && playlistIdSet.has(routeId)) {
143	                this.writePersistedActivePlaylistId(routeId);
144	                return;
145	            }
146	
147	            if (selectedId && playlistIdSet.has(selectedId)) {
148	                this.writePersistedActivePlaylistId(selectedId);
149	                return;
150	            }
151	
152	            if (
153	                !routeId &&
154	                !selectedId &&
155	                storedId &&
156	                playlistIdSet.has(storedId)
157	            ) {
158	                this.activatePlaylist(storedId);
159	                return;
160	            }
161	
162	            if (storedId && !playlistIdSet.has(storedId)) {
163	                this.clearPersistedActivePlaylistId();
164	            }
165	        });
166	
167	        this.router.events
168	            .pipe(
169	                filter(
170	                    (event): event is NavigationEnd =>
171	                        event instanceof NavigationEnd
172	                ),
173	                takeUntilDestroyed(this.destroyRef)
174	            )
175	            .subscribe((event) => {
176	                this.syncFromUrl(event.urlAfterRedirects);
177	            });
178	    }
179	
180	    syncFromUrl(url = this.router.url): PlaylistRouteContext {
181	        this.currentUrl.set(url);
182	        const routeContext = this.routeContext();
183	
184	        this.rememberSection(routeContext);
185	
186	        if (routeContext.playlistId) {
187	            this.activatePlaylist(routeContext.playlistId);
