270	            inWorkspace: this.isWorkspaceRoute(url),
271	            provider: (match?.[1] as PortalProvider | undefined) ?? null,
272	            playlistId: match?.[2] ?? null,
273	            section: (match?.[3] as PortalRailSection | undefined) ?? null,
274	        };
275	    }
