277	    private rememberSection(routeContext: PlaylistRouteContext): void {
278	        if (!routeContext.provider || !routeContext.section) {
279	            return;
280	        }
281	
282	        const normalized = this.normalizeSectionForProvider(
283	            routeContext.section,
284	            routeContext.provider
285	        );
286	        if (!normalized) {
287	            return;
288	        }
289	
290	        const memory = this.readSectionMemory();
291	        memory.providers[routeContext.provider] = normalized;
292	        if (routeContext.playlistId) {
293	            memory.playlists[routeContext.playlistId] = {
294	                provider: routeContext.provider,
295	                section: normalized,
296	                updatedAt: Date.now(),
297	            };
298	        }
299	        this.writeSectionMemory(memory);
300	    }
301	
302	    private resolveTargetSection(
303	        provider: PortalProvider,
304	        currentSection: PortalRailSection | null,
305	        targetPlaylistId: string
306	    ): string {
307	        const fromCurrent = this.normalizeSectionForProvider(
308	            currentSection,
309	            provider
310	        );
311	        if (fromCurrent) {
312	            return fromCurrent;
313	        }
314	
315	        if (provider === 'playlists' && currentSection) {
316	            return 'all';
317	        }
318	
319	        const memory = this.readSectionMemory();
320	        const playlistMemory = memory.playlists[targetPlaylistId];
321	        if (playlistMemory?.provider === provider) {
322	            const normalizedPlaylistSection = this.normalizeSectionForProvider(
323	                playlistMemory.section,
324	                provider
325	            );
326	            if (normalizedPlaylistSection) {
327	                return normalizedPlaylistSection;
328	            }
329	        }
330	
331	        const providerMemory = memory.providers[provider];
332	        const normalizedProviderSection = this.normalizeSectionForProvider(
333	            providerMemory,
334	            provider
335	        );
336	        if (normalizedProviderSection) {
337	            return normalizedProviderSection;
338	        }
339	
340	        if (provider === 'playlists') {
341	            return 'all';
342	        }
343	
344	        return 'vod';
345	    }
346	
347	    private supportsSectionNavigation(provider: PortalProvider): boolean {
348	        if (provider === 'xtreams') {
349	            return Boolean(window.electron);
350	        }
351	
352	        return true;
353	    }
354	
355	    private normalizeSectionForProvider(
356	        section: string | null | undefined,
357	        provider: PortalProvider
358	    ): string | null {
359	        if (!section) {
360	            return null;
361	        }
362	
363	        if (provider === 'xtreams') {
364	            if (section === 'itv') {
365	                return 'live';
366	            }
367	
368	            return XTREAM_SECTIONS.includes(
369	                section as (typeof XTREAM_SECTIONS)[number]
370	            )
371	                ? section
372	                : null;
373	        }
374	
375	        if (provider === 'playlists') {
376	            return M3U_SECTIONS.includes(
377	                section as (typeof M3U_SECTIONS)[number]
378	            )
379	                ? section
380	                : null;
381	        }
382	
383	        if (section === 'live') {
384	            return 'itv';
385	        }
386	        if (section === 'recently-added') {
387	            return 'recent';
388	        }
389	
390	        return STALKER_SECTIONS.includes(
391	            section as (typeof STALKER_SECTIONS)[number]
392	        )
393	            ? section
394	            : null;
395	    }
396	
397	    private readSectionMemory(): PlaylistSectionMemory {
398	        const empty: PlaylistSectionMemory = { providers: {}, playlists: {} };
399	
400	        try {
401	            this.clearLegacySectionMemory();
402	            const raw = localStorage.getItem(LAST_SECTION_STORAGE_KEY);
403	            if (!raw) {
404	                return empty;
405	            }
406	            const parsed = JSON.parse(raw);
407	            if (typeof parsed !== 'object' || parsed === null) {
408	                return empty;
409	            }
410	
411	            const providers: Partial<Record<PortalProvider, string>> = {};
412	            const playlists: PlaylistSectionMemory['playlists'] = {};
413	
414	            const parsedProviders = (parsed as Record<string, unknown>)[
415	                'providers'
416	            ];
417	            if (typeof parsedProviders === 'object' && parsedProviders !== null) {
418	                const candidate = parsedProviders as Record<string, unknown>;
419	                if (typeof candidate['playlists'] === 'string') {
420	                    providers.playlists = candidate['playlists'];
421	                }
422	                if (typeof candidate['xtreams'] === 'string') {
423	                    providers.xtreams = candidate['xtreams'];
424	                }
425	                if (typeof candidate['stalker'] === 'string') {
426	                    providers.stalker = candidate['stalker'];
427	                }
428	            }
429	
430	            const parsedPlaylists = (parsed as Record<string, unknown>)[
431	                'playlists'
432	            ];
433	            if (
434	                typeof parsedPlaylists === 'object' &&
435	                parsedPlaylists !== null
436	            ) {
437	                Object.entries(
438	                    parsedPlaylists as Record<string, unknown>
439	                ).forEach(([playlistId, value]) => {
440	                    if (!value || typeof value !== 'object' || !playlistId) {
441	                        return;
442	                    }
443	
444	                    const row = value as Record<string, unknown>;
445	                    const provider = row['provider'];
446	                    const section = row['section'];
447	                    const updatedAt = row['updatedAt'];
448	                    const isProviderValid =
449	                        provider === 'playlists' ||
450	                        provider === 'xtreams' ||
451	                        provider === 'stalker';
452	                    if (!isProviderValid || typeof section !== 'string') {
453	                        return;
454	                    }
455	
456	                    playlists[playlistId] = {
457	                        provider,
458	                        section,
459	                        updatedAt:
460	                            typeof updatedAt === 'number'
461	                                ? updatedAt
462	                                : Date.now(),
463	                    };
464	                });
465	            }
466	
467	            return { providers, playlists };
468	        } catch {
469	            return empty;
470	        }
471	    }
472	
473	    private writeSectionMemory(memory: PlaylistSectionMemory): void {
474	        try {
475	            localStorage.setItem(
476	                LAST_SECTION_STORAGE_KEY,
477	                JSON.stringify(memory)
478	            );
479	        } catch {
480	            // Ignore storage write failures.
481	        }
482	    }
483	
484	    private removeDeletedPlaylistsFromSectionMemory(
485	        existingIds: string[]
486	    ): void {
487	        const existingIdSet = new Set(existingIds);
488	        const memory = this.readSectionMemory();
489	        const currentEntries = Object.entries(memory.playlists);
490	        if (currentEntries.length === 0) {
491	            return;
492	        }
493	
494	        const nextPlaylists: PlaylistSectionMemory['playlists'] = {};
495	        let hasChanges = false;
496	
497	        currentEntries.forEach(([playlistId, entry]) => {
498	            if (!existingIdSet.has(playlistId)) {
499	                hasChanges = true;
500	                return;
501	            }
502	
503	            const normalizedSection = this.normalizeSectionForProvider(
504	                entry.section,
505	                entry.provider
506	            );
507	            if (!normalizedSection) {
508	                hasChanges = true;
509	                return;
510	            }
511	
512	            nextPlaylists[playlistId] = {
513	                ...entry,
514	                section: normalizedSection,
515	            };
516	        });
517	
518	        if (!hasChanges) {
519	            return;
520	        }
521	
522	        this.writeSectionMemory({
523	            providers: memory.providers,
524	            playlists: nextPlaylists,
525	        });
526	    }
527	
528	    private readPersistedActivePlaylistId(): string | null {
529	        try {
530	            const value = localStorage.getItem(
531	                LAST_ACTIVE_PLAYLIST_STORAGE_KEY
532	            );
533	            return value && value.trim().length > 0 ? value : null;
534	        } catch {
535	            return null;
536	        }
537	    }
538	
539	    private writePersistedActivePlaylistId(playlistId: string): void {
540	        try {
541	            localStorage.setItem(LAST_ACTIVE_PLAYLIST_STORAGE_KEY, playlistId);
542	        } catch {
543	            // Ignore storage write failures.
544	        }
545	    }
546	
547	    private clearPersistedActivePlaylistId(): void {
548	        try {
549	            localStorage.removeItem(LAST_ACTIVE_PLAYLIST_STORAGE_KEY);
550	        } catch {
551	            // Ignore storage write failures.
552	        }
553	    }
554	
555	    private clearLegacySectionMemory(): void {
556	        try {
557	            if (!localStorage.getItem(LEGACY_LAST_SECTION_STORAGE_KEY)) {
558	                return;
559	            }
560	
561	            localStorage.removeItem(LEGACY_LAST_SECTION_STORAGE_KEY);
562	        } catch {
563	            // Ignore storage read/write failures.
564	        }
565	    }
566	}
