.playlist-switcher-trigger {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 4px 8px 4px 4px;
    border-radius: 10px;
    cursor: pointer;
    transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
    background: color-mix(in srgb, var(--app-on-surface) 5%, transparent);
    border: 1px solid
        color-mix(in srgb, var(--mat-sys-outline-variant) 36%, transparent);
    app-region: no-drag;

    &:hover {
        background: color-mix(
            in srgb,
            var(--app-on-surface) 12%,
            transparent
        );
        border-color: color-mix(
            in srgb,
            var(--mat-sys-outline-variant) 64%,
            transparent
        );
    }

    &.is-open {
        background: color-mix(
            in srgb,
            var(--app-on-surface) 12%,
            transparent
        );
        border-color: color-mix(
            in srgb,
            var(--mat-sys-outline-variant) 72%,
            transparent
        );
    }

    &:active {
        transform: scale(0.98);
    }
}

.trigger-icon-container {
    width: 30px;
    height: 30px;
    border-radius: 8px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    background: color-mix(
        in srgb,
        var(--app-on-surface) 8%,
        transparent
    );
    flex-shrink: 0;
}

.trigger-playlist-icon {
    font-size: 18px;
    width: 18px;
    height: 18px;
    color: var(--mat-sys-on-surface-variant);
}

.playlist-info {
    flex: 1;
    min-width: 0;
    max-width: 240px;

    .name {
        font-size: 0.95em;
        font-weight: 600;
        overflow: hidden;
        text-overflow: ellipsis;
        white-space: nowrap;
        line-height: 1.25;
        letter-spacing: 0.01em;
    }

    .channels-count {
        font-size: 0.74em;
        line-height: 1.3;
        letter-spacing: 0.02em;
        color: var(--mat-sys-on-surface-variant);
    }
}

.dropdown-icon {
    font-size: 20px;
    width: 20px;
    height: 20px;
    color: var(--mat-sys-on-surface-variant);
    transition: transform 0.25s cubic-bezier(0.4, 0, 0.2, 1);
    margin-left: auto;

    &.rotated {
        transform: rotate(180deg);
    }
}

::ng-deep .playlist-switcher-menu.mat-mdc-menu-panel {
    --mat-menu-container-color: var(--mat-sys-surface-container-high);
    width: min(
        var(--playlist-switcher-overlay-width, 360px),
        calc(100vw - 24px)
    ) !important;
    min-width: min(
        var(--playlist-switcher-overlay-width, 360px),
        calc(100vw - 24px)
    ) !important;
    max-width: min(
        var(--playlist-switcher-overlay-width, 360px),
        calc(100vw - 24px)
    ) !important;
    margin-top: -1px !important;
    border-radius: 0 0 12px 12px !important;
    border: 1px solid var(--mat-sys-outline) !important;
    border-top: 0 !important;
    overflow: hidden !important;
    background: var(--mat-menu-container-color) !important;

    .mat-mdc-menu-content {
        padding: 0 !important;
        background: var(--mat-menu-container-color) !important;
    }
}

.menu-header {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 14px 16px 10px;
    font-size: 0.85em;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    opacity: 0.7;

    mat-icon {
        font-size: 18px;
        width: 18px;
        height: 18px;
    }
}

.search-container {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 8px 12px;
    margin: 0 8px 4px;
    background: color-mix(
        in srgb,
        var(--app-on-surface) 6%,
        transparent
    );
    border-radius: 8px;
    border: 1px solid transparent;
    transition: all 0.2s ease;
}

.search-container:focus-within {
    border-color: var(--mat-sys-primary);
    background: var(--mat-sys-surface-container-highest);
}

.search-container .search-icon {
    font-size: 18px;
    width: 18px;
    height: 18px;
    color: var(--mat-sys-on-surface-variant);
}

.search-container .search-input {
    flex: 1;
    border: none;
    background: transparent;
    outline: none;
    font-size: 0.86em;
    font-weight: 500;
    line-height: 1.4;
    color: inherit;
    min-width: 0;
}

.search-container .search-input::placeholder {
    color: var(--mat-sys-on-surface-variant);
}

.search-container .clear-btn {
    width: 24px;
    height: 24px;
    line-height: 24px;
    padding: 0;
}

.search-container .clear-btn mat-icon {
    font-size: 16px;
    width: 16px;
    height: 16px;
}

.type-filters {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
    padding: 0 8px 8px;
    margin-top: 6px;
}

.type-filter-chip {
    height: 24px;
    padding: 0 10px;
    border-radius: 999px;
    border: 1px solid
        color-mix(in srgb, var(--mat-sys-outline-variant) 72%, transparent);
    background: color-mix(
